@dataclass(frozen=True)
class _ClassTrainerRoute:
    room_vnum: str
    room_name: str
    keyword: str
    steps: tuple[tuple[str, str, str], ...]
    minimum_level: int = 10
    search_room_vnum: str | None = None
    open_before: frozenset[tuple[str, str]] = frozenset()
    research_only: bool = False
    locator_routes: tuple[tuple[str, tuple[str, ...]], ...] = ()

    @property
    def outbound(self) -> dict[str, str]:
        return {origin: command for origin, command, _ in self.steps}

    def command_for(
        self,
        room_vnum: str,
        previous_room_vnum: str | None = None,
    ) -> str | None:
        """Return the next route command without collapsing repeated rooms."""
        candidates = [
            (index, command)
            for index, (origin, command, _) in enumerate(self.steps)
            if origin == room_vnum
        ]
        if len(candidates) == 1:
            return candidates[0][1]
        for index, command in candidates:
            if index and self.steps[index - 1][0] == previous_room_vnum:
                return command
        return None

    @property
    def destination_vnum(self) -> str:
        return self.search_room_vnum or self.room_vnum

    @property
    def return_commands(self) -> tuple[str, ...]:
        return tuple(
            _OPPOSITE_DIRECTIONS[command]
            for _, command, _ in reversed(self.steps)
        )

    @property
    def return_to_healer(self) -> dict[str, str]:
        return {
            destination: _OPPOSITE_DIRECTIONS[command]
            for _, command, destination in self.steps
        }

    @property
    def healer_return_paths(self) -> dict[str, tuple[str, ...]]:
        commands = ["south"]
        paths = {"3001": tuple(commands)}
        for _, command, destination in self.steps:
            commands.append(command)
            paths[destination] = tuple(commands)
        return paths


@lru_cache(maxsize=8)
def _source_subclass_trainer_route(
    character_class: str,
    subclass: str,
) -> _ClassTrainerRoute | None:
    """Build a level-30 route from the source-reset subclass teacher."""
    source_directory = Path("runs/dd4-source/server/area")
    if not source_directory.is_dir():
        return None
    world = load_world_source(source_directory, include_all_areas=True)
    source_route = source_subclass_teacher_route(
        world,
        subclass,
        character_class=character_class,
        preferred_mobile_vnums=(31002,)
        if character_class == "smithy"
        else (),
    )
    if source_route is None:
        return None
    return _ClassTrainerRoute(
        room_vnum=str(source_route.room_vnum),
        room_name=source_route.room_name,
        keyword=source_route.keyword,
        steps=source_route.steps,
        minimum_level=30,
        open_before=frozenset(source_route.open_before),
    )


@lru_cache(maxsize=8)
def _source_class_trainer_route(
    character_class: str,
) -> _ClassTrainerRoute | None:
    """Build the level-10 route from the current Midgaard area files."""
    source_directory = Path("runs/dd4-source/server/area")
    if not source_directory.is_dir():
        return None
    world = load_world_source(source_directory, include_all_areas=True)
    fallback_route = _CLASS_TRAINERS.get(character_class.casefold())
    source_route = source_class_teacher_route(
        world,
        character_class,
        preferred_room_vnum=(
            int(fallback_route.destination_vnum)
            if fallback_route is not None
            else None
        ),
    )
    if source_route is None:
        return None
    return _ClassTrainerRoute(
        room_vnum=str(source_route.room_vnum),
        room_name=source_route.room_name,
        keyword=source_route.keyword,
        steps=source_route.steps,
        minimum_level=10,
        open_before=frozenset(source_route.open_before),
    )


