class StarterRuntimeCapReached(RuntimeError):
    """Signal the starter's controlled runtime boundary to its campaign."""


async def _close_connection_bounded(
    connection: CommandConnection,
    *,
    timeout: float,
) -> None:
    """Close a transport without letting cancellation wait forever."""
    close_timeout = max(0.05, float(timeout))
    close_task = asyncio.create_task(connection.close())

    async def cancel_and_drain() -> None:
        if close_task.done():
            return
        close_task.cancel()
        try:
            await close_task
        except BaseException:
            pass

    try:
        await asyncio.wait_for(asyncio.shield(close_task), timeout=close_timeout)
    except asyncio.CancelledError:
        # ``wait_for`` waits for the cancelled starter task to finish. Keep
        # the transport close in its own task, give it one bounded chance, and
        # then cancel it so the outer liveness boundary can return.
        try:
            await asyncio.wait_for(
                asyncio.shield(close_task),
                timeout=close_timeout,
            )
        except BaseException:
            await cancel_and_drain()
        raise
    except (ConnectionError, OSError, TimeoutError):
        await cancel_and_drain()


def _consume_task_result(task: asyncio.Task[Any]) -> None:
    try:
        task.result()
    except BaseException:
        pass


async def _send_command_hard_bounded(
    connection: CommandConnection,
    command: str,
    *,
    timeout: float,
) -> None:
    """Bound command writes without awaiting a cancellation-resistant drain."""
    send_task = asyncio.create_task(connection.send_command(command))
    try:
        done, _pending = await asyncio.wait(
            (send_task,),
            timeout=max(0.01, timeout),
        )
    except BaseException:
        if not send_task.done():
            send_task.cancel()
            send_task.add_done_callback(_consume_task_result)
        raise
    if not done:
        send_task.cancel()
        send_task.add_done_callback(_consume_task_result)
        raise TimeoutError(f"send_command exceeded its {timeout:g} second bound")
    send_task.result()


async def _read_available_hard_bounded(
    connection: CommandConnection,
    *,
    adapter_timeout: float,
    hard_timeout: float,
) -> ReadResult:
    """Bound an adapter read without awaiting a cancellation-resistant task."""
    read_task = asyncio.create_task(
        connection.read_available(timeout=adapter_timeout)
    )
    try:
        done, _pending = await asyncio.wait(
            (read_task,),
            timeout=max(0.01, hard_timeout),
        )
    except BaseException:
        if not read_task.done():
            read_task.cancel()
            read_task.add_done_callback(_consume_task_result)
        raise
    if not done:
        read_task.cancel()
        read_task.add_done_callback(_consume_task_result)
        raise TimeoutError("read_available exceeded its hard timeout")
    return read_task.result()


async def _load_character_password_with_timeout(
    credential_name: str,
    timeout: float,
) -> str:
    """Load a keyring password without allowing a blocked backend to stall the loop."""
    loop = asyncio.get_running_loop()
    result: asyncio.Future[str | BaseException] = loop.create_future()

    def finish(value: str | BaseException) -> None:
        if result.done():
            return
        result.set_result(value)

    def publish(value: str | BaseException) -> None:
        try:
            loop.call_soon_threadsafe(finish, value)
        except RuntimeError:
            # The runner may be shutting down after the timeout fired.
            pass

    def load() -> None:
        try:
            value = load_character_password(credential_name)
        except BaseException as exc:
            publish(exc)
        else:
            publish(value)

    # A daemon thread is deliberate: keyring backends can block in an OS
    # permission prompt, and a cancelled executor future would keep shutdown
    # waiting for that backend.
    threading.Thread(target=load, name="dd4-keyring", daemon=True).start()
    value = await asyncio.wait_for(result, timeout=timeout)
    if isinstance(value, BaseException):
        raise value
    return value
