@dataclass(frozen=True)
class BotDecision:
    command: str
    reason: str
    secret: bool = False
    wait_seconds: float = 0.0


def _decision_payload(decision: BotDecision, stage: str) -> dict[str, Any]:
    metadata = classify_decision(decision.command, decision.reason, stage)
    return {
        "stage": stage,
        "reason": decision.reason,
        "command": "[REDACTED]" if decision.secret else decision.command,
        "redacted": decision.secret,
        "category": metadata.category,
        "safety_critical": metadata.safety_critical,
    }


def _connection_inactivity_timeout(policy: object, default: float) -> float:
    """Shorten transport acknowledgement waits during bounded logout cleanup."""
    if (
        bool(getattr(policy, "runtime_boundary_requested", False))
        and bool(getattr(policy, "midgaard_logout_pending", False))
    ):
        return min(default, _RUNTIME_BOUNDARY_ACK_TIMEOUT_SECONDS)
    return default


def _runtime_boundary_safe_healer(
    policy: object,
    state: CharacterState,
) -> bool:
    """Recognize a healer checkpoint where a stalled logout can stop safely."""
    return bool(
        getattr(policy, "runtime_boundary_requested", False)
        and getattr(policy, "midgaard_logout_pending", False)
        and state.room_vnum == "3054"
        and not state.dead
        and state.hp is not None
        and state.hp > 0
        and not _is_uncommandable(state)
        and not state.in_combat
        and not getattr(policy, "combat_active", False)
        and not _enemy_records(state.enemies)
    )


def _runtime_boundary_room_arrival_acknowledges_command(
    policy: object,
    state: CharacterState,
    command_origin_room: str | None,
) -> bool:
    """Accept a safe healer arrival when DD4 omits the follow-up prompt."""
    return bool(
        command_origin_room
        and command_origin_room != "3054"
        and _runtime_boundary_safe_healer(policy, state)
    )


@dataclass(frozen=True)
class FieldHuntStop:
    route: tuple[str, ...]
    target: str | None = None
    where_target: str | None = None
    command_keyword: str | None = None
    actions: tuple[str, ...] = ()
    where_location_routes: tuple[tuple[str, tuple[str, ...]], ...] = ()
    where_relocation_routes: tuple[
        tuple[str, str, tuple[str, ...]], ...
    ] = ()
    maximum_where_relocations: int = 0
    abort_if_where_target_absent: bool = False
    abort_if_where_target_unlisted: bool = False
    abort_if_where_room_names: tuple[str, ...] = ()
    post_actions: tuple[str, ...] = ()
    required_items: tuple[str, ...] = ()
    allowed_bystanders: tuple[str, ...] = ()
    trivial_bystanders: tuple[str, ...] = ()
    rejected_consider_subjects: tuple[str, ...] = ()
    accepted_consider_fragments: tuple[str, ...] = ()
    rejected_consider_fragments: tuple[str, ...] = ()
    minimum_health_ratio: float = _FIELD_CONTINUE_HEALTH_RATIO
    consider_only: bool = False
    exact_target: bool = False
    maximum_target_count: int = 1
    require_isolated: bool = False
    crowd_retry_limit: int = 0
    crowd_retry_delay_seconds: float = 0.0
    allow_local_recovery: bool = False
    # Permit sleep only at an explicitly source-audited no-mob transit room;
    # ordinary field stops continue to recover at the Midgaard healer.
    allow_transit_recovery: bool = False
    # Some routes begin in a normal room and end at the audited waypoint. They
    # must travel before auditing the first room as a sleep location.
    allow_transit_recovery_at_start: bool = True
    # Source route planners can raise this above the normal 90% transit
    # recovery floor when the next leg needs nearly a full movement pool.
    transit_recovery_minimum_move: int = 0
    allow_below_band_for_required_loot: bool = False
    allow_below_band_for_source_coins: bool = False
    # Some required-loot routes have a source-audited, unavoidable gate mob.
    # Consider the exact live VNUM before allowing the gate fight; this is a
    # route safety exception, never progression evidence.
    route_gate_source_mobile_vnums: tuple[int, ...] = ()
    # A gate may be a fixed, below-band mobile that must be removed to reach a
    # locator-confirmed required-loot carrier.  This is opt-in because a low
    # consider normally means "do not spend a combat round".
    route_gate_allow_below_band: bool = False
    # Keep the exception tied to the source room where the gate was audited.
    route_gate_room_vnums: tuple[str, ...] = ()
    # Do not open a route gate merely because a stale room snapshot contains
    # its mobile; require the preceding bounded locator to confirm the carrier.
    route_gate_requires_locator_target: bool = False
    # A required-loot endpoint may defer one source-audited, below-band hazard
    # until after the exact carrier is killed.  This never permits an engaged
    # hazard; the post-objective cleanup/recovery gates still own that case.
    deferred_required_loot_hazard_source_mobile_vnums: tuple[int, ...] = ()
    # Scan the immediate destination before entering a required-loot endpoint
    # that a wandering source mobile can make unsafe between packets.
    pre_entry_scan_room_vnums: tuple[str, ...] = ()
    pre_entry_scan_hazard_source_mobile_vnums: tuple[int, ...] = ()
    route_gate_minimum_health_ratio: float = 0.90
    require_sanctuary: bool = False
    minimum_combat_health_ratio: float = 0.0
    route_vnums: tuple[str, ...] = ()
    maximum_level_offset: int | None = None
    maximum_pursuit_steps: int = 1
    pursuit_room_vnums: tuple[str, ...] = ()
    selective_loot_keywords: tuple[str, ...] = ()
    abort_after_consider_rejection: bool = False
    abort_if_where_location_unknown: bool = False
    preserve_where_route_waypoints: bool = False
    source_mobile_vnum: int | None = None
    source_mobile_room_description: str | None = None
    source_reset_room_vnum: str | None = None
    source_peak_round_damage: int | None = None
    source_critical_hit_damage: int | None = None
    # These bounds are used when a route requires sanctuary. They preserve
    # the raw source values above while proving the protected damage window.
    protected_source_peak_round_damage: int | None = None
    protected_source_critical_hit_damage: int | None = None
    # A source incoming bound does not prove that this character can defeat a
    # high-health target before its recovery reserves are exhausted.
    require_damage_window_probe: bool = False
    damage_window_minimum_fraction: float = _FIELD_DAMAGE_WINDOW_MINIMUM_FRACTION
    source_target_hp_ceiling: int | None = None
    source_policy_id: str | None = None
    source_target_armed: bool | None = None
    source_loot_object_vnums: tuple[int, ...] = ()
    source_specials: tuple[str, ...] = ()
    # Source-ranked circuit legs can cross reboot-randomized room components.
    # Keep their source graph as a preference, but let the live GMCP graph
    # choose the actual exits for this stop.
    live_navigation_target: str | None = None
    live_navigation_entry_room: str | None = None
    live_navigation_start_index: int | None = None
    live_navigation_resume_index: int | None = None
    live_navigation_room_vnums: tuple[str, ...] = ()
    live_navigation_blocked_room_vnums: tuple[str, ...] = ()
    live_navigation_preferred_destinations: tuple[str, ...] = ()
    # A source-audited no-mob waypoint can still contain a fixed NPC that
    # DD4 proves cannot interact with this character. Keep those identities
    # explicit; every other live room target remains a hard stop.
    transit_allowed_bystanders: tuple[str, ...] = ()


_FASTWALK_COMMAND_BUDGET_RESERVE = 128
_FASTWALK_STOP_COMMAND_OVERHEAD = 4


def _fastwalk_command_budget(
    route: Fastwalk,
    hunt_stops: Collection[FieldHuntStop],
) -> int:
    """Allow a finite hunt circuit to finish without removing its hard cap."""
    stop_work = sum(
        len(stop.route_vnums)
        + len(stop.route)
        + len(stop.actions)
        + len(stop.post_actions)
        + _FASTWALK_STOP_COMMAND_OVERHEAD
        for stop in hunt_stops
    )
    # Reserve the registered route once in each direction for a failed recall
    # and leave a bounded allowance for combat, loot, and healer cleanup.
    return (
        2 * len(route.commands)
        + stop_work
        + _FASTWALK_COMMAND_BUDGET_RESERVE
    )


