        self.fastwalk_require_invisibility = fastwalk_require_invisibility or bool(
            self.fastwalk_route is not None
            and "invisibility" in self.spec.identity.capabilities
        )
        self.fastwalk_hunt_stops = fastwalk_hunt_stops
